css:
.d-cf3d{position:relative;box-sizing:border-box;width:300px;max-width:100%;height:148px;padding:0;border:0;background:none;font:inherit;color:inherit;text-align:left;perspective:900px;cursor:pointer;-webkit-tap-highlight-color:transparent}
.d-cf3d-in{position:absolute;inset:0;display:block;transform-style:preserve-3d;transition:transform 280ms cubic-bezier(.34,1.56,.64,1)}
.d-cf3d-on .d-cf3d-in{transform:rotateY(180deg)}
.d-cf3d-face{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;gap:8px;padding:12px 16px;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:var(--paper);box-shadow:inset 0 1px 0 #fff5;backface-visibility:hidden}
.d-cf3d-back{transform:rotateY(180deg);gap:2px}
.d-cf3d-k{font-family:var(--font-mono);font-size:11px;letter-spacing:.08em;color:var(--faint);text-transform:uppercase}
.d-cf3d-name{font-size:21px;font-weight:650;letter-spacing:-.01em;color:var(--ink)}
.d-cf3d-note{font-size:11px;color:var(--muted)}
.d-cf3d-row{display:flex;justify-content:space-between;gap:8px;padding:2px 0;border-bottom:1px solid var(--line);font-size:11px}
.d-cf3d-row:last-child{border-bottom:0}
.d-cf3d-v{font-family:var(--font-mono);color:var(--ink)}
.d-cf3d:focus-visible{outline:1px solid var(--ink);outline-offset:2px}

init:
root => {
  const box = root.querySelector('.d-cf3d');
  if (!box) return;
  box.onclick = () => {
    const on = !box.classList.contains('d-cf3d-on');
    box.classList.toggle('d-cf3d-on', on);
    box.setAttribute('aria-pressed', on ? 'true' : 'false');
  };
}
